ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent;RAW=ROOT/'results/branch_node_perturbation_20261023';credit=json.loads((RAW/'credit_results.json').read_text());gates=json.loads((RAW/'gate_results.json').read_text());done=json.loads((RAW/'completion.json').read_text());assert done['complete'] and len(credit)==320 and len(gates)==32
