def filt(depth,kind='analytic',noise=None,feedback=None,k=None):return [r for r in credit if r['depth']==depth and (r['kind'],r.get('noise'),r.get('feedback'),r.get('k'))==(kind,noise,feedback,k)]
def avg(z,key):return st.mean(x[key] for x in z)
def seed_values(z,key):return [st.mean(x[key] for x in z if x['seed']==s) for s in range(532,536)]
def gate(method,small=False):return [r for r in gates if r['method']==method and r['small_noise_control']==small]
def gtext(z):return f"{100*avg(z,'query_accuracy'):.2f}% (seed SD {100*st.stdev(seed_values(z,'query_accuracy')):.2f} pp)"
def profile(depth,kind,noise=None,feedback=None,k=None):return next(r['median_ms'] for r in profiles['rows'] if r['depth']==depth and (r['kind'],r.get('noise'),r.get('feedback'),r.get('k'))==(kind,noise,feedback,k))
